#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.assign(n, 0);
    if (n == 0) return;

    int P = omp_get_max_threads();
    if (P < 1) P = 1;
    if (P > n) P = n;

    std::vector<long long> blockSum(P, 0LL);   // sum of each block
    std::vector<long long> suffixAdd(P + 1, 0LL); // suffix sums of blockSum; suffixAdd[P]=0

    #pragma omp parallel num_threads(P)
    {
        const int tid = omp_get_thread_num();

        // Deterministic contiguous block partition
        const int base = n / P;
        const int rem  = n % P;
        const int start = tid * base + (tid < rem ? tid : rem);
        const int len   = base + (tid < rem ? 1 : 0);
        const int end   = start + len; // exclusive

        long long local = 0;
        // Compute reverse prefix sum within the block (from right to left)
        for (int i = end - 1; i >= start; --i) {
            local += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(local);
        }
        blockSum[tid] = local;

        #pragma omp barrier

        // One thread computes suffix sums of block totals to propagate across blocks
        #pragma omp single
        {
            suffixAdd[P] = 0LL;
            for (int t = P - 1; t >= 0; --t) {
                suffixAdd[t] = suffixAdd[t + 1] + blockSum[t];
            }
        }

        #pragma omp barrier

        // Add the sum of all blocks to the right to each element in this block
        const long long add = suffixAdd[tid + 1];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + add);
        }
    }
}
