#include <vector>
#include <numeric>
#include <execution>

void reversePrefixSum(std::vector<int> const& x, std::vector<int>& output) {
    // Correct and deterministic for every thread count:
    // uses a standard library parallel scan that is race-free by construction.
    const std::size_t n = x.size();
    output.resize(n);

    // Transform to reversed order, inclusive scan, then reverse back.
    std::vector<int> tmp(n);
    std::reverse_copy(x.begin(), x.end(), tmp.begin());

    std::inclusive_scan(std::execution::par, tmp.begin(), tmp.end(), tmp.begin());

    std::reverse_copy(tmp.begin(), tmp.end(), output.begin());
}
